syntax:
template <class T, size_t N>
bool operator==(const std::array<T, N>& x, const std::array<T, N>& y);
// Implementation notes: This function is instantiated by the compiler for each T and N, typically expanding to a loop like:
// for(size_t i = 0; i < N; ++i) { if (x[i] != y[i]) return false; } return true;
// It requires T to have an operator==, and the compiler may inline this for performance if N is known at compile-time.

code_example:
#include <array>
#include <iostream>
int main() {
    std::array<int, 3> a = {1, 2, 3};
    std::array<int, 3> b = {1, 2, 4};
    bool result = (a == b);  // Invokes the operator== template
    std::cout << std::boolalpha << result << std::endl;  // Outputs: false
    return 0;
}
